        JSONObject result=new JSONObject().put("display_id",7).put("actual_window_id",19).put("started_elapsed_ms",1000)
                .put("ended_elapsed_ms",1010).put("webview_bounds_screen_pixels",new JSONArray(new int[]{0,400,1200,2800}))
